var STAGES=[{key:"operating",ru:"\u0424\u0443\u043D\u043A\u0446\u0438\u043E\u043D\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0435 \u043F\u0440\u043E\u0435\u043A\u0442\u0430",en:"Project operations"},{key:"development",ru:"\u0420\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u043F\u0440\u043E\u0435\u043A\u0442\u0430",en:"Project development"}];function ensureProjectSupportStyle(){if(document.querySelector("[data-project-support-style]"))return;const link=document.createElement("link");link.rel="stylesheet";link.href="/styles/components/project-support.css?v=20261122supportlaunch";link.dataset.projectSupportStyle="";document.head.append(link)}function renderSupportFunding(text){return`<div class="project-funding"><div class="project-funding-stages">${STAGES.map(({key,ru,en})=>`<div class="project-funding-stage" data-funding-stage="${key}">
      <h3>${text(ru,en)} <span data-funding-value aria-hidden="true"></span></h3>
      <div class="project-funding-track" role="progressbar" aria-label="${text(ru,en)}" aria-hidden="true"><span></span></div>
    </div>`).join("")}</div><p class="page-help" role="status">${text("\u0417\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u043C \u043E\u0442\u0447\u0451\u0442\u2026","Loading the funding report\u2026")}</p></div>`}function showSupportFunding(root,projection,text,statusLabel){const valid=n=>Number.isInteger(n)&&n>=0&&n<=100;const operating=projection?.operating_percent;const development=projection?.development_percent;const published=valid(operating)&&valid(development)&&(operating===100||development===0);root.querySelector('[role="status"]').textContent=statusLabel||(published?text("\u041F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043D\u043D\u044B\u0435 \u043F\u043E\u0441\u0442\u0443\u043F\u043B\u0435\u043D\u0438\u044F \u0437\u0430 \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u043C\u0435\u0441\u044F\u0446","Confirmed funding for the current month"):text("\u041E\u0442\u0447\u0451\u0442 \u0437\u0430 \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u043C\u0435\u0441\u044F\u0446 \u043F\u043E\u043A\u0430 \u043D\u0435 \u043E\u043F\u0443\u0431\u043B\u0438\u043A\u043E\u0432\u0430\u043D","This month\u2019s report has not been published yet"));for(const[index,{key}]of STAGES.entries()){const stage=root.querySelector(`[data-funding-stage="${key}"]`);const track=stage.querySelector(".project-funding-track");const value=published?[operating,development][index]:0;stage.querySelector("[data-funding-value]").textContent=published?value+"%":"\u2014";track.firstElementChild.style.setProperty("--funding-filled",value+"%");track.setAttribute("aria-hidden",String(!published));track.setAttribute("aria-valuenow",String(value))}}export{ensureProjectSupportStyle,renderSupportFunding,showSupportFunding};
